  "安全区、触控密度、底部导航和分类页。": "안전 영역, 터치 밀도, 하단 탐색 및 카테고리 페이지.",
  "安全区、动态视口、顶部栏、底部导航、Bottom/Action/Filter Sheet、下拉刷新、无限加载、滑动操作、滚轮选择、键盘避让、移动认证与结算、权限和离线状态都有稳定契约，可直接用于移动网页、PWA 和 Tauri/Electron 移动式 WebView。": "안전 영역, 동적 뷰포트, 상단 표시줄, 하단 탐색, 하단/작업/필터 시트, 당겨서 새로 고침, 무한 로드, 슬라이딩 작업, 휠 선택, 키보드 회피, 모바일 인증 및 결제, 권한 및 오프라인 상태가 안정적인 계약을 가지며 모바일 웹 페이지, PWA 및 Tauri/Electron 모바일 WebView에 직접 사용할 수 있습니다.",
