  "按最小字段宽度自动换行": "최소 필드 너비로 래핑",
  "把 506 个 CSS 组件和 72 种 DOM 行为映射为 AngularJS 元素/属性指令，提供模块工厂、严格组件子集、原生 ngModel、十轴主题、3 个可注入服务、动态生命周期与相互隔离的 Tauri / Electron 入口。它面向必须维护 AngularJS 1.8.x 的存量产品，并明确公开框架 EOL 安全边界。": "506개의 CSS 구성 요소와 72개의 DOM 동작을 AngularJS 요소/속성 지시어로 매핑하여 모듈 팩토리, 엄격한 구성 요소 하위 설정, 기본 ngModel, 10축 테마, 3개의 주입 가능한 서비스, 동적 수명 주기 및 격리된 Tauri/Electron 항목을 제공합니다. 이는 AngularJS 1.8.x를 유지해야 하는 재고 제품을 대상으로 하며 프레임워크의 EOL 보안 경계를 명시적으로 노출합니다.",
  "把 Web 技术变成完整桌面工作区": "웹 기술을 완전한 데스크탑 작업 공간으로 전환",
  "白底中性默认": "흰색 바탕에 중립 기본값",
