  "白色画布、中性色文本、4px 基础圆角、克制阴影。圆角和强层次必须显式选择，不会污染普通业务页面。": "흰색 캔버스, 중립 텍스트, 4px 기본 둥근 모서리, 억제된 그림자. 둥근 모서리와 강력한 계층 구조는 명시적으로 선택되어야 하며 일반 비즈니스 페이지를 오염시키지 않습니다.",
  "版本、发行说明、延后/重启更新": "버전, 릴리스 노트, 업데이트 연기/다시 시작",
