  "绑定行为并访问实例": "바인딩 동작 및 액세스 인스턴스",
  "包裹；容器小于 768px 会独立折叠，不受浏览器窗口宽度干扰。": "포장; 768px보다 작은 컨테이너는 브라우저 창 너비에 관계없이 독립적으로 축소됩니다.",
  "包含每一项，适合 AI 和构建工具直接读取。": "AI 및 빌드 도구를 통한 직접 읽기에 적합한 모든 항목이 포함되어 있습니다.",
  "包明确支持 Node.js >=18.18、Chrome/Edge/Firefox 100+、Safari/iOS 15.4+ 和 ESM；主入口及桌面适配器提供条件": "패키지는 Node.js >=18.18, Chrome/Edge/Firefox 100+, Safari/iOS 15.4+ 및 ESM을 명시적으로 지원합니다. 메인 포털 및 데스크탑 어댑터는 조건을 제공합니다",
  "包入口": "패키지 항목",
  "包入口可在服务端安全导入，全部 506 个组件均经过逐项 SSR，行为只在 Effect 生命周期内初始化；服务端标记 Hydration 不产生 recoverable error，并兼容 StrictMode。Tauri 与 Electron 分别使用": "패키지 항목을 서버 측에서 안전하게 가져올 수 있습니다. 506개의 모든 구성 요소는 항목별 SSR을 거쳤으며 동작은 효과 수명 주기 동안에만 초기화됩니다. 서버 측 표시 Hydration은 복구 가능한 오류를 생성하지 않으며 StrictMode와 호환됩니다. Tauri와 Electron이 각각 사용됩니다.",
  "保持兼容，可继续作为业务级壳使用。": "호환성이 유지되며 비즈니스 수준 셸로 계속 사용할 수 있습니다.",
  "保持为外部 peer dependency，不会把它打进 Gardenerim 产物，也不会掩盖框架级风险。新项目优先选择 Vue、React 或框架无关入口；存量项目必须同时执行输入净化、CSP、资源白名单、桌面桥最小授权和迁移计划。完整要求见": "이를 Gardenerim 제품에 적용하지 않고 프레임워크 수준 위험을 다루지 않는 외부 피어 종속성으로 유지합니다. 새로운 프로젝트에는 Vue, React 또는 프레임워크 독립적인 입구를 선택할 우선권이 부여됩니다. 기존 프로젝트에서는 입력 삭제, CSP, 리소스 화이트리스트, 데스크톱 브리지 최소 인증 및 마이그레이션 계획도 구현해야 합니다. 전체 요구사항은 다음을 참조하세요.",
  "保存": "저장",
  "保存草稿": "초안 저장",
