  "报告与发票": "보고서 및 송장",
  "暴露 beforeapproval、beforeclose、beforefilepicker、beforeopen、beforepromptstop、beforepromptsubmit、beforetabclose 7 个必须在 JS/.NET 异步边界前同步阻止的守卫事件。行为成员与事件 detail 契约可从": "beforeapproval, beforeclose, beforefilepicker, beforeopen, beforepromptstop, beforepromptsubmit, beforetabclose JS/.NET 비동기 경계 전에 동기적으로 차단되어야 하는 7개의 가드 이벤트가 노출됩니다. 행동 회원 및 이벤트 세부 계약은 다음에서 가능합니다.",
