  "标签、分栏、Dock、检查器和状态栏都保持高密度、小圆角和完整键盘路径。": "레이블, 열, Dock, Inspector 및 상태 표시줄은 모두 고밀도, 작고 둥근 모서리 및 전체 키보드 경로를 유지합니다.",
