  "表达 Dirty、Saving、Saved 和 Error，并支持延迟保存及立即保存。": "Dirty, Saving, Saved 및 Error를 표현하며 지연 및 즉시 저장을 지원합니다.",
  "表单、导航、浮层、数据、媒体、商业、通信、法律、工作流和 Dashboard 均有稳定结构与状态约定。": "양식, 탐색, 오버레이, 데이터, 미디어, 비즈니스, 통신, 법률, 작업 흐름 및 대시보드는 모두 안정적인 구조와 상태 규칙을 가지고 있습니다.",
  "表单不再从一堆 Input 开始": "양식은 더 이상 여러 개의 입력으로 시작되지 않습니다.",
