  "不要再为下一张页面重新发明基础设施。": "다음 페이지를 위해 인프라 재창조를 중단하세요.",
  "不要在 Renderer 开启 Node Integration，也不要向页面暴露任意 IPC。适配器只接受 minimize、maximize、close、drag 白名单动作。": "렌더러에서 노드 통합을 활성화하지 말고 IPC를 페이지에 노출하지 마십시오. 어댑터는 화이트리스트 최소화, 최대화, 닫기 및 끌기 작업만 허용합니다.",
  "不遮挡内容的补充优先使用 Help Text、Inline Hint 或 Tip；必须绑定控件时使用 Tooltip；包含链接和操作时使用 Help Popover；跨步骤教学使用 Tour。不要把重要错误或必须阅读的法律信息藏进悬浮层。": "콘텐츠를 차단하지 않는 보충 콘텐츠에 대해서는 도움말 텍스트, 인라인 힌트 또는 팁을 사용하세요. 컨트롤을 바인딩해야 하는 경우 도구 설명을 사용하세요. 링크와 작업을 포함할 때 도움말 팝오버를 사용하세요. 크로스 스텝 교육을 위해 Tour를 사용하세요. 플로팅 레이어에 중요한 오류나 꼭 읽어야 할 법적 정보를 숨기지 마세요.",
