  "布局、表单、导航、数据、内容、账号、商业、移动、桌面和 AI 均可独立引入。": "레이아웃, 양식, 탐색, 데이터, 콘텐츠, 계정, 커머스, 모바일, 데스크톱 및 AI를 모두 독립적으로 도입할 수 있습니다.",
  "布局使用逻辑属性，组件覆盖 RTL 下的动画方向与箭头。": "레이아웃은 논리적 속성을 사용하고 구성 요소는 RTL 아래의 애니메이션 방향과 화살표를 재정의합니다.",
