  "初始化根节点自身及其后代的全部行为。": "루트 노드 자체와 그 하위 항목의 모든 동작을 초기화합니다.",
  "处理复杂 CustomEvent。值会转换为 .NET 字符串、布尔、数字、数组或字典；DOM、File、BigInt、函数和循环引用会安全序列化。": "복잡한 CustomEvent를 처리합니다. 값은 .NET 문자열, 부울, 숫자, 배열 또는 사전으로 변환됩니다. DOM, 파일, BigInt, 함수 및 순환 참조는 안전하게 직렬화됩니다.",
