  "窗口 Chrome、导航、编辑区、状态区和宿主桥接各有独立契约。": "윈도우 크롬, 네비게이션, 편집 영역, 상태 영역, 호스트 브리지는 각각 독립적인 계약을 갖고 있습니다.",
  "创建标准内部部件，避免破坏 CSS 和行为选择器契约。": "CSS 및 동작 선택기 계약 위반을 방지하기 위해 표준 내부를 만듭니다.",
  "创建并管理 Toast": "토스트 생성 및 관리",
  "创建插件。": "플러그인을 생성합니다.",
  "创建空间": "공간 생성",
