  "从": "부터",
  "从 52 个成品结构中选择最接近的页面骨架。": "완성된 구조 52개 중에서 가장 가까운 페이지 뼈대를 선택합니다.",
  "从第一次登录，到每一次安全审计": "최초 로그인부터 모든 보안감사까지",
  "从第一行 CSS 到几十万套 AI 生成模板，这里描述 Gardenerim 的稳定接口、选择顺序、环境矩阵和交付边界。": "CSS의 첫 번째 줄부터 수십만 세트의 AI 생성 템플릿까지 Gardenerim의 안정적인 인터페이스, 선택 순서, 환경 매트릭스 및 전달 경계에 대한 설명은 다음과 같습니다.",
  "从静态 SSR 到桌面 WebView，使用同一套 Razor 组件": "동일한 Razor 구성 요소 세트를 사용하여 정적 SSR에서 데스크톱 WebView로",
  "从看见商品，到交易与退款完成": "상품을 보시고 거래완료 및 환불까지",
  "从逻辑 inline-start 方向偏移": "논리적 인라인 시작 방향으로부터의 오프셋",
  "从企业站主导航到 CMS 树，从移动底栏到 Electron Activity Bar，从右键菜单到 Scrollspy，38 种稳定模式让 AI 直接按意图选择。": "기업 사이트 소유자 탐색부터 CMS 트리까지, 모바일 하단 표시줄부터 Electron Activity Bar까지, 마우스 오른쪽 버튼 클릭 메뉴부터 Scrollspy까지 38가지 안정적인 모드를 통해 AI가 의도에 따라 직접 선택할 수 있습니다.",
  "从上传一个文件，到完成整套内容生产": "파일 업로드부터 전체 콘텐츠 제작 완료까지",
  "从上下主区、左右栏到 Holy Grail、Master / Detail、Dock、可调分栏和全屏工作区，Web、移动端与 Tauri / Electron 直接选用，不必临时编写页面级布局 CSS。": "상단 및 하단 메인 영역부터 왼쪽 및 오른쪽 열부터 Holy Grail, Master/Detail, Dock, 조정 가능한 열 및 전체 화면 작업 공간, 웹, 모바일 터미널 및 Tauri/Electron까지 페이지 수준 레이아웃 CSS를 임시로 작성할 필요 없이 직접 선택할 수 있습니다.",
  "从事件载荷取值": "이벤트 페이로드에서 값 가져오기",
  "从完整系统开始。": "완전한 시스템으로 시작하십시오.",
  "从选中一项，到处理十万条记录": "항목 1개 선택부터 100,000건 처리까지",
