  "从一个按钮到超级 CMS": "버튼 하나부터 슈퍼CMS까지",
  "从组件库，走到可以直接生成的完整页面": "컴포넌트 라이브러리에서 직접 생성할 수 있는 전체 페이지로 이동합니다.",
  "粗体": "굵은 글씨",
  "促销列表": "프로모션 목록",
  "存在配方时，不从零拼装高复用页面。": "레시피가 있는 경우 재사용률이 높은 페이지가 처음부터 정리되지 않습니다.",
