  "打印端使用": "인쇄면용",
  "打印时 Reel、Scroll Area、Scroll Snap、Masonry、Imposter、Overlay 和 Sticky Region 自动展平，避免内容被裁掉。": "릴, 스크롤 영역, 스크롤 스냅, 벽돌, 임포스터, 오버레이 및 고정 영역은 인쇄 시 내용이 잘리는 것을 방지하기 위해 자동으로 병합됩니다.",
  "打印时固定、粘性、全屏和分栏被展平成普通文档流；分隔手柄自动隐藏。": "인쇄 시 고정, 고정, 전체 화면 및 기둥 형식이 일반 문서 흐름으로 병합됩니다. 구분선 핸들은 자동으로 숨겨집니다.",
  "打印时交互栏、筛选、加载遮罩和浮动按钮隐藏；页头和结果页展平，错误说明与请求编号仍保留。": "인쇄 시 상호작용 막대, 필터, 마스크 로딩 및 플로팅 버튼이 숨겨집니다. 헤더와 결과 페이지는 평면화되고 오류 설명과 요청 번호는 계속 유지됩니다.",
  "打印时隐藏窗口 Chrome、活动栏、状态栏、工具栏、Bottom Panel 和所有浮层，展开主内容、Dock 与 Inspector，避免裁切。": "인쇄할 때 창 Chrome, 활동 표시줄, 상태 표시줄, 도구 모음, 하단 패널 및 모든 플로팅 레이어를 숨기고 기본 콘텐츠, Dock 및 Inspector를 확장하여 잘림을 방지합니다.",
  "打印隐藏 Tooltip、Popover、Tour、Spotlight、Hotspot 与反馈动作，保留 Tip、Callout、Note 和排错正文。": "도구 설명, 팝오버, 둘러보기, 스포트라이트, 핫스팟 및 피드백 작업을 인쇄 및 숨기고 팁, 콜아웃, 메모 및 문제 해결 텍스트를 유지합니다.",
  "打印与文档输出": "인쇄 및 문서 출력",
