  "定义高频页面根类、所有必要部件、适用平台、行为、桌面适配器和用途。它不是截图模板，而是可换主题、可响应、可继续组合的稳定结构。以下展开项保留每个配方的全部字段。": "고주파수 페이지 루트 클래스, 필요한 모든 구성요소, 적용 가능한 플랫폼, 동작, 데스크탑 어댑터 및 사용법을 정의합니다. 스크린샷 템플릿이 아닌, 테마로 변경이 가능하고 반응성이 뛰어나며 지속적으로 결합될 수 있는 안정적인 구조입니다. 다음 확장은 각 레시피의 모든 필드를 유지합니다.",
