  "断网仍告知数据安全状态。": "네트워크 연결이 끊어져도 데이터 보안 상태가 계속 알려집니다.",
  "对比度、包边界、导出和版本": "대비, 패킷 경계, 내보내기 및 버전",
  "对话": "대화",
  "对话、Composer 与流式回答之外，还需要推理摘要、工具调用和批准、多 Agent 编排、来源引用、Artifact、上下文记忆、Token/费用、语音、权限、隐私、安全复核与反馈评估。Gardenerim 将整条 AI 任务链做成可直接复用的32种模式。": "대화 외에도 작성기 및 스트리밍 답변, 추론 요약, 도구 호출 및 승인, 다중 에이전트 오케스트레이션, 소스 인용, 아티팩트, 상황별 메모리, 토큰/수수료, 음성, 권한, 개인 정보 보호, 보안 검토 및 피드백 평가도 필요합니다. Gardenerim는 전체 AI 작업 체인을 직접 재사용할 수 있는 32가지 모드로 만듭니다.",
  "对话与预览/代码/文档双区布局": "대화상자 및 미리보기/코드/문서 이중 영역 레이아웃",
