  "返回": "반품",
  "返回、标题与尾部动作": "반환, 제목 및 꼬리 작업",
  "返回的 packed、unpacked 和文件数。2.1.0 以封版的 2.0.0 实测结果为紧邻基线，限制每个产物 raw 增长不超过 2%、gzip/Brotli 不超过 3%，npm 包 packed 不超过 3%、unpacked 不超过 2%、文件数不超过 10%；五个平台产物均拥有直接历史基线。包体测量向上取整到 4 KiB packed 与 64 KiB unpacked，形成不低估真实包体且不受性能报告自包含压缩循环影响的确定性上界。绝对上限或相对上限任一失败都会阻断发布。": "압축, 압축 해제 및 반환된 파일 수입니다. 2.1.0은 봉인된 버전 2.0.0의 실제 측정 결과를 즉각적인 기준으로 사용하여 각 제품의 원시 성장을 2% 이하, gzip/Brotli를 3% 이하, npm 패키지를 3% 이하, 압축을 푼 경우 2% 이하, 파일 수를 10% 이하로 제한합니다. 5가지 플랫폼 제품은 모두 직접적인 역사적 기준을 가지고 있습니다. 포함 볼륨 측정값은 압축된 4KiB 및 압축되지 않은 64KiB로 반올림되어 실제 포함 볼륨을 과소평가하지 않고 성능 보고서의 자체 포함 압축 주기에 영향을 받지 않는 결정론적 상한을 형성합니다. 절대 한도 또는 상대적 한도가 실패하면 릴리스가 차단됩니다.",
  "返回对象允许调用的全部成员。": "호출이 허용된 개체의 모든 구성원을 반환합니다.",
