  "分栏、命令、菜单、导航、Dock、托盘和 About Dialog": "열, 명령, 메뉴, 탐색, Dock, 트레이 및 정보 대화 상자",
  "分栏认证": "컬럼인증",
  "分栏认证在 704px 以下收敛为单列；卡片在 384px 以下重排 QR、规则与恢复码；底部操作尊重 Safe Area。": "열 인증은 704px 미만의 단일 열로 수렴됩니다. 카드는 384px 미만의 QR, 규칙 및 복구 코드로 재정렬됩니다. 하단 작업은 안전 영역을 존중합니다.",
