  "服务器错误、请求编号和重试": "서버 오류, 요청 번호 및 재시도",
  "浮层、Dialog、Toast 等稳定堆叠顺序": "플로팅 레이어, 다이얼로그, 토스트 등의 안정적인 스택 순서",
  "浮层支持 top / bottom / start / end 与 start / center / end 对齐，空间不足时自动翻转并限制在视口内；RTL 会交换逻辑方向。": "플로팅 레이어는 상단/하단/시작/끝 및 시작/가운데/끝 정렬을 지원합니다. 공간이 부족하면 자동으로 반전되어 뷰포트로 제한됩니다. RTL은 논리적 방향을 교환합니다.",
