  "复用桌面菜单项；在线状态、窗口入口与退出": "데스크탑 메뉴 항목을 재사용합니다. 온라인 상태, 창 진입 및 종료",
  "复杂但高复用的页面已经组合为配方。AI 应先选配方，再用组件和工具类做有限调整。": "복잡하지만 재사용 가능성이 높은 페이지가 레시피로 결합되었습니다. AI는 먼저 레시피를 선택한 다음 구성 요소와 도구 클래스를 사용하여 제한적으로 조정해야 합니다.",
