  "覆盖窗口、工作区、标签、命令、快捷键、文件、托盘、更新、通知和恢复状态。": "창, 작업 공간, 탭, 명령, 바로 가기, 파일, 트레이, 업데이트, 알림 및 복원 상태를 다룹니다.",
  "覆盖单个列": "단일 열 덮어쓰기",
  "覆盖对话、Composer、Prompt、Thinking、工具批准、Agent、Artifact、生成、上下文、费用、权限、安全、语音和反馈。": "대화, 작성기, 프롬프트, 사고, 도구 승인, 에이전트, 아티팩트, 빌드, 컨텍스트, 요금, 권한, 보안, 음성 및 피드백을 다룹니다.",
  "覆盖规则：": "재정의 규칙:",
  "覆盖基础原子、通用组件、高密度后台、移动端、内容商业化、AI 工作区与桌面 WebView。默认足够克制，组合能力足够宽。": "기본 원자, 공통 구성 요소, 고밀도 백엔드, 모바일 단말, 콘텐츠 상용화, AI 작업 공간 및 데스크톱 WebView를 다룹니다. 기본은 충분히 억제되어 있고 조합 능력도 충분히 넓습니다.",
  "覆盖目录、SKU、购物车、结算、履约、支付、订单、订阅、账单、退款和税费。": "카탈로그, SKU, 카트, 체크아웃, 이행, 결제, 주문, 구독, 청구, 환불 및 세금을 다룹니다.",
  "覆盖内在响应、RTL、容器查询、Bento、Masonry、滚动吸附、安全区和打印结构。已有": "내장 응답, RTL, 컨테이너 쿼리, Bento, Masonry, 스크롤 스냅, 안전 영역 및 인쇄 구조를 다룹니다. 이미",
  "覆盖全部根类、业务字段组、动态增删、条件显示、容器响应、RTL 与打印。": "모든 루트 클래스, 비즈니스 필드 그룹, 동적 추가 및 삭제, 조건부 표시, 컨테이너 응답, RTL 및 인쇄를 다룹니다.",
  "覆盖全部模式并可直接测试 OTP、密码强度、倒计时、账号/租户选择和身份菜单。": "모든 모드를 포괄하며 OTP, 비밀번호 강도, 카운트다운, 계정/테넌트 선택 및 ID 메뉴를 직접 테스트할 수 있습니다.",
  "覆盖全局、层级、选择、菜单、页内、流程、移动与桌面导航，并可直接测试键盘和右键交互。": "전역, 계층, 선택, 메뉴, 페이지 내, 프로세스, 모바일 및 데스크톱 탐색을 다루며 키보드 및 마우스 오른쪽 버튼 클릭 상호 작용을 직접 테스트할 수 있습니다.",
  "覆盖上传、文件浏览、媒体、图片、文档、音视频、四类编辑器、协作、版本和存储。": "업로드, 파일 탐색, 미디어, 사진, 문서, 오디오 및 비디오, 4가지 유형의 편집기, 공동 작업, 버전 및 저장을 다룹니다.",
  "覆盖所有根类、RTL/移动响应、Tooltip、Popover、FAQ 与两步 Tour。": "모든 루트 클래스, RTL/모바일 반응형, 도구 설명, 팝오버, FAQ 및 2단계 둘러보기를 다룹니다.",
  "覆盖所有页头、公共栏、Loading、Empty、Error、403、404、500、Offline、Maintenance、Container Query 和 Back to Top。": "모든 헤더, 공통 필드, 로드 중, 비어 있음, 오류, 403, 404, 500, 오프라인, 유지 관리, 컨테이너 쿼리 및 맨 위로 이동을 다룹니다.",
