  "可变高度内容列；columns / min / gap，窄容器单列": "가변 높이 콘텐츠 열; 열/최소/간격, 좁은 컨테이너 단일 열",
  "可调分栏": "조정 가능한 기둥",
  "可访问性、响应与环境规则": "접근성, 대응성 및 환경 규칙",
  "可复用筛选条件": "재사용 가능한 필터 조건",
  "可关闭组件自动初始化， 方便由页面级运行时统一接管。显式传入的行为 data attribute 优先于生成默认值。": "페이지 수준 런타임에 의한 통합 인계를 용이하게 하기 위해 자동 구성요소 초기화를 끌 수 있습니다. 데이터 속성을 명시적으로 전달하는 동작은 기본값 생성보다 우선합니다.",
  "可滚动区域应可被键盘聚焦并提供可访问名称；Reduced Motion 会取消原语的平滑滚动。": "스크롤 가능한 영역은 키보드로 초점을 맞출 수 있어야 하며 접근 가능한 이름을 제공해야 합니다. 모션 감소는 프리미티브의 부드러운 스크롤을 억제합니다.",
  "可机器验证": "기계 검증 가능",
  "可切换公共网站、Dashboard、CRM、行业门户与状态中心预览。": "전환 가능한 공개 웹사이트, 대시보드, CRM, 산업 포털 및 상태 센터 미리보기.",
  "可取消 Before 事件、Approved/Rejected/Cancelled、Reset API": "이벤트 전 취소 가능, 승인/거부/취소, 재설정 API",
  "可取消流程守卫": "프로세스 가드를 취소할 수 있습니다.",
  "可使用": "가능",
  "可选索引文本": "선택적 인덱스 텍스트",
  "可以跨 32 种页面复用，保证 AI 在换行业时不改变基础语法。": "는 32가지 유형의 페이지에 걸쳐 재사용될 수 있어 산업 변화 시 AI의 기본 구문이 변경되지 않도록 보장합니다.",
  "可用工具类包括": "사용 가능한 도구 클래스는 다음과 같습니다.",
  "可用值": "사용 가능한 값",
  "可直接测试 App Bar、Bottom Navigation、Swipe Tabs、Swipe Actions、Infinite Load、Action/Filter Sheet 与移动选择器。": "앱 바, 하단 탐색, 스와이프 탭, 스와이프 작업, 무한 로드, 작업/필터 시트 및 모바일 선택기를 직접 테스트합니다.",
  "可直接测试排序、选择、展开、列显隐、搜索、视图切换、移动堆叠表和键盘网格。": "정렬, 선택, 확장, 열 가시성, 검색, 보기 전환, 스택 테이블 이동, 키보드 그리드를 직접 테스트할 수 있습니다.",
  "可直接测试全选、反选、范围选择、Transfer、Picker、Cascader、Saved Choice 和动态 Builder。": "모두 선택, 역선택, 범위 선택, 전송, 선택기, 캐스케이더, 저장된 선택 및 동적 빌더를 직접 테스트할 수 있습니다.",
  "可直接供 AI、代码生成器和文档工具读取。全量压缩包实测为 328,129 B raw、50,581 B gzip、26,733 B Brotli；单个": "AI, 코드 생성기 및 문서 도구에서 직접 읽을 수 있습니다. 전체 압축 패키지의 실제 측정값은 328,129 B raw, 50,581 B gzip, 26,733 B Brotli입니다. 싱글",
  "可直接供 AI、代码生成器和文档工具读取。全量压缩包实测为 405,932 B raw、59,850 B gzip、30,016 B Brotli；单个": "AI, 코드 생성기 및 문서 도구에서 직접 읽을 수 있습니다. 전체 압축 패키지의 실제 측정값은 405,932 B raw, 59,850 B gzip, 30,016 B Brotli입니다. 싱글",
  "可直接供 AI、代码生成器和文档工具读取。全量压缩包预算为 330,691 B raw、52,236 B gzip、27,220 B Brotli；单个": "AI, 코드 생성기 및 문서 도구에서 직접 읽을 수 있습니다. 전체 압축 패키지의 예산은 330,691 B raw, 52,236 B gzip, 27,220 B Brotli입니다. 싱글",
