  "框架类型": "프레임 종류",
  "框架提供焦点样式、减少动效、高对比和 Forced Colors 基础，但语义名称与内容顺序仍由页面作者负责。": "프레임워크는 초점 스타일, 동작 감소, 고대비 및 강제 색상에 대한 기반을 제공하지만 의미 체계 명명 및 콘텐츠 순서는 여전히 페이지 작성자의 책임입니다.",
  "扩展": "확장",
  "了解发布状态": "릴리스 상태 이해",
  "类。": "클래스.",
  "类必须出现在“CSS 全量 API”或“工具类”清单；每个组件、运行时和页面配方还必须出现在各自目录。构建校验会逐文件计算 SHA-256，避免目录落后于源码。": "클래스는 CSS 전체 API 또는 도구 클래스 목록에 나타나야 합니다. 각 구성 요소, 런타임 및 페이지 레시피도 해당 디렉터리에 나타나야 합니다. 빌드 확인은 파일별로 SHA-256을 계산하여 디렉터리가 소스 코드보다 뒤처지는 것을 방지합니다.",
  "类名": "클래스 이름",
  "类型，并保留默认语义标签、选择器、状态、部件、行为、平台与无障碍元数据。静态 SSR 阶段直接输出完整 HTML，建立交互连接后才挂载 DOM 行为；参数签名改变会刷新挂载，组件释放时会注销监听器。": "기본 의미 체계 태그, 선택기, 상태, 위젯, 동작, 플랫폼 및 접근성 메타데이터를 입력하고 유지합니다. 정적 SSR 단계는 완전한 HTML을 직접 출력하고 대화형 연결을 설정한 후에만 DOM 동작을 마운트합니다. 매개변수 서명을 변경하면 마운트가 새로 고쳐지고 구성 요소가 릴리스되면 리스너가 로그아웃됩니다.",
  "类型、所有者、校验值和版权": "유형, 소유자, 값 확인 및 저작권",
  "类型安全监听 gardener:* 事件": "정원사를 위한 유형 안전 청취:* 이벤트",
  "离线横幅": "오프라인 배너",
  "离线状态、本地数据安全和重连": "오프라인 상태, 로컬 데이터 보안 및 재접속",
  "里程碑和状态历史": "마일스톤 및 상태 기록",
  "立即发布": "즉시 석방",
  "例如：auth、--g-color、data-g-mode、keyframe": "예: auth, --g-color, data-g-mode, keyframe",
  "例如：grid-cols、padding-inline、print-hidden": "예: Grid-cols, padding-inline, print-hidden",
  "连续构建并逐文件验证 SHA": "SHA 파일을 파일별로 지속적으로 구축 및 검증",
  "联系邮箱": "연락처 이메일",
  "链接可能已经失效。": "링크가 만료되었을 수 있습니다.",
  "两者都明确占据整行": "둘 다 명시적으로 전체 줄을 차지합니다.",
  "聊天 · 工具 · Artifact": "채팅 · 도구 · 유물",
  "聊天、Agent、生成工具": "채팅, 에이전트, 생성 도구",
  "列、偏移、起止线、显示状态和 gutter 都可响应": "열, 오프셋, 시작 및 끝 줄, 표시 상태 및 여백이 모두 반응합니다.",
  "列表": "목록",
  "列表 / 详情 / 检查器": "목록/상세정보/검사자",
  "列表、表格或树的选择边界": "목록, 테이블 또는 트리의 선택 경계",
  "列宽": "열 너비",
  "列显示与隐藏": "열 표시 및 숨기기",
  "列显隐并至少保留一列": "열을 숨기고 하나 이상의 열을 유지합니다.",
  "林海教育": "임해교육",
  "零运行时依赖": "런타임 종속성 없음",
  "另有 print offset、start、end、hidden、visible": "인쇄 오프셋, 시작, 끝, 숨김, 표시도 있습니다",
  "刘海、圆角屏和 Home Indicator 四边保护": "노치, 둥근 화면 및 홈 인디케이터 4면 보호",
  "刘海屏与 Home Indicator 自动保护。": "노치 및 홈 표시기 자동 보호.",
  "浏览器支持时继承父网格轨道": "브라우저가 지원하는 경우 상위 그리드 트랙 상속",
  "流程与文档": "프로세스 및 문서화",
  "流式消息、工具、Agent、Artifact 与生成状态。": "스트리밍 메시지, 도구, 에이전트, 아티팩트 및 빌드 상태.",
  "六个新增声明式行为": "6개의 새로운 선언적 동작",
  "录制": "녹음",
  "路由失效、搜索和首页入口": "라우팅실패, 검색 및 홈페이지 진입",
  "逻辑方向属性": "논리적 방향 속성",
  "逻辑方向属性覆盖 RTL；Reduced Motion 停止同步脉冲；Forced Colors 为当前 Activity/Tab/Command 提供明确轮廓。": "논리적 방향 속성이 RTL을 재정의합니다. 감소된 동작은 동기화 펄스를 중지합니다. 강제 색상은 현재 활동/탭/명령에 대한 명확한 개요를 제공합니다.",
  "逻辑方向属性支持 RTL；Reduced Motion 关闭位移过渡；Forced Colors 强化选中轮廓；打印自动展平外壳。": "논리적 방향 속성은 RTL을 지원합니다. 모션 감소는 변위 전환을 끕니다. 강제 색상은 선택한 윤곽을 향상시킵니다. 인쇄하면 껍질이 자동으로 편평해집니다.",
  "没有": "없음",
  "没有结果": "결과 없음",
  "没有匹配的 {framework} 组件。": "일치하는 {framework} 구성요소가 없습니다.",
  "没有匹配的 CSS 接口。": "일치하는 CSS 인터페이스가 없습니다.",
  "没有匹配的工具类。": "일치하는 도구 클래스가 없습니다.",
  "没有匹配的组件。": "일치하는 구성요소가 없습니다.",
  "媒体上叠工具、标注、状态；align / justify / margin": "미디어 오버레이 도구, 주석, 상태; 정렬 / 양쪽 정렬 / 여백",
  "媒体资产工作台与详情栏": "미디어 자산 워크벤치 및 세부정보 표시줄",
  "每份自定义构建清单还会为可读 CSS、压缩 CSS、Source Map 和随包复制的 Tauri/Electron 适配器生成 SHA-256 与标准 SRI。接收方无需依赖构建机器，即可逐文件验证交付内容是否完整且未被替换。": "각 사용자 정의 빌드 매니페스트는 읽기 가능한 CSS, 압축 CSS, 소스 맵 및 패키지와 함께 복사된 Tauri/Electron 어댑터에 대한 SHA-256 및 표준 SRI도 생성합니다. 수신자는 빌드 시스템에 의존하지 않고도 전달이 완료되었고 대체되지 않았음을 파일별로 확인할 수 있습니다.",
  "每个 CSS 组件都有对应的": "각 CSS 구성요소에는 해당하는",
  "每个公共组件都能解析到完整所属包，并明确列出连带包含项。": "각 공용 구성 요소는 자신이 속한 전체 패키지를 확인하며 명시적인 포함 항목이 나열됩니다.",
