  "默认白色 Surface 与 4px 小圆角；组件只使用主题 Token，可在 42 套主色和所有正交主题轴中复用。": "4px의 작은 둥근 모서리가 있는 기본 흰색 표면. 구성 요소는 42개 기본 색상 세트와 모든 직교 테마 축에서 재사용할 수 있는 테마 토큰만 사용합니다.",
  "默认白色 Surface、1px 边框和 4px 小圆角；阴影仅用于命令面板、窗口切换器和菜单等真实浮层。": "기본 흰색 표면, 1px 테두리 및 4px 작은 둥근 모서리. 그림자는 명령 패널, 창 전환기 및 메뉴와 같은 실제 오버레이에만 사용됩니다.",
  "默认白色 Surface、1px 边框与 4px 小圆角；大圆角和强阴影不是移动端默认。": "기본 흰색 표면, 1px 테두리 및 4px 작은 둥근 모서리; 크고 둥근 모서리와 강한 그림자는 모바일의 기본값이 아닙니다.",
  "默认导入。Gardenerim 包本身不会读取全局 AngularJS，根入口可安全用于 SSR 工具链分析。": "기본적으로 가져옵니다. Gardenerim 패키지 자체는 전역 AngularJS를 읽지 않으며 루트 항목은 SSR 툴체인 분석에 안전합니다.",
  "默认风格适合个人、企业、后台和内容站，不预设强烈品牌人格。": "기본 스타일은 개인, 기업, 백엔드 및 콘텐츠 스테이션에 적합하며 강력한 브랜드 개성을 미리 설정하지 않습니다.",
  "默认视觉：": "기본 시각적 개체:",
  "默认小圆角，可显式扩展": "기본적으로 작은 둥근 모서리, 명시적으로 확장 가능",
