  "仍会如实显示 AngularJS 本体的已知公告；这属于必须隔离、接受或迁移的遗留风险，不能标记为已修复。": "AngularJS 온톨로지에 대해 알려진 권고 사항은 여전히 충실하게 표시됩니다. 이는 격리, 수용 또는 마이그레이션해야 하는 레거시 위험이며 수정된 것으로 표시할 수 없습니다.",
