  "上表列出 12 个主要 CSS/Runtime 入口；预算文件还逐项覆盖 2 个桌面适配器、28 个组件包，共 42 个正式压缩产物，没有使用笼统的共享上限替代单产物检查。": "위 표에는 12개의 주요 CSS/런타임 항목이 나열되어 있습니다. 또한 예산 문서에는 단일 제품 검사를 대체하기 위한 일반 공유 한도를 사용하지 않고 데스크톱 어댑터 2개, 구성 요소 패키지 28개, 공식 압축 제품 총 42개에 대한 적용 범위가 항목화되어 있습니다.",
