  "十一套闭合 Schema、48 个标准 Schema 用例、10 个构建专项用例、66 个运行时单元测试、152 个真实浏览器用例与 24 个结构用例": "폐쇄형 스키마 11세트, 표준 스키마 사용 사례 48개, 빌드별 사용 사례 10개, 런타임 단위 테스트 66개, 실제 브라우저 사용 사례 125개, 구조적 사용 사례 24개",
