  "实现 CSS 或 Runtime。": "CSS 또는 런타임을 구현합니다.",
  "使用": "사용",
  "使用 {theme} 主题": "{theme} 테마 사용",
  "使用 704px 容器折叠；文件浏览、媒体详情、图片编辑器、文档缩略图、Markdown 双栏和版本对比均有移动布局。": "704px 컨테이너 축소를 사용합니다. 파일 브라우저, 미디어 세부 정보, 이미지 편집기, 문서 축소판, Markdown 이중 열 및 버전 비교에는 모두 모바일 레이아웃이 있습니다.",
  "使用 Ajv 2020-12 执行 48 个标准验证用例，覆盖十份发布/配置文档、未知根字段、十类未知嵌套字段、十类缺失嵌套必填字段、跨 Schema 引用、JavaScript 标识符、SHA-256 格式、基线回归状态和旧组件 Schema 兼容别名；": "Ajv 2020-12를 사용하여 10개의 릴리스/구성 문서, 알 수 없는 루트 필드, 10가지 유형의 알 수 없는 중첩 필드, 10가지 유형의 누락된 중첩 필수 필드, 교차 스키마 참조, JavaScript 식별자, SHA-256 형식, 기준 회귀 상태 및 레거시 구성 요소 스키마 호환 별칭을 다루는 48개의 표준 검증 사용 사례를 실행했습니다.",
  "使用 gzip level 9 与 Brotli quality 11，对全部 42 个正式压缩产物同时计算 raw、gzip 和 Brotli，并检查全量 CSS、Runtime 的压缩比例，以及": "gzip 레벨 9 및 Brotli 품질 11을 사용하여 42개 공식 압축 제품 전체에 대해 raw, gzip 및 Brotli를 동시에 계산하고 전체 CSS, Runtime 및 Brotli의 압축 비율을 확인합니다.",
  "使用 Node.js 内置测试运行器和 Happy DOM，对公共清单中的全部 72 种行为逐项双向比对真实实例成员，并验证初始化、幂等性、销毁和重新初始化；同时覆盖 MutationObserver 的动态节点、动态属性、子树移除、作用域销毁、多行为共存、全局销毁和初始化事件冒泡。": "Node.js 내장 테스트 실행기와 Happy DOM을 사용하여 공개 목록의 모든 72개 동작에 대해 실제 인스턴스 멤버를 양방향으로 비교하고 초기화, 멱등성, 파괴 및 재초기화를 확인합니다. MutationObserver의 동적 노드, 동적 속성, 하위 트리 제거, 범위 파괴, 다중 동작 공존, 전역 파괴 및 초기화 이벤트 버블링을 다룹니다.",
  "使用 TypeScript 严格模式编译真实消费者，覆盖默认及命名导出、行为工厂、Toast、实例查询和两类桌面桥接。": "TypeScript 엄격 모드를 사용하여 기본 및 명명된 내보내기, 동작 팩토리, 알림, 인스턴스 쿼리 및 두 가지 유형의 데스크톱 브리지를 다루는 실제 소비자를 컴파일합니다.",
  "使用场景": "사용 시나리오",
  "使用企业 SSO": "엔터프라이즈 SSO 사용",
  "使用已登记组件填充功能。": "등록된 구성 요소로 기능을 채웁니다.",
  "使用预览环境确认内容，再发布到生产环境。": "프로덕션 환경에 게시하기 전에 미리보기 환경을 사용하여 콘텐츠를 확인하세요.",
