  "示例": "예시",
  "示例与 Home 的 HTML 结构": "홈의 예시 및 HTML 구조",
  "事件": "이벤트",
  "事件名": "이벤트 이름",
  "视口或容器中间内容；min / padding": "뷰포트 또는 컨테이너 중앙에 있는 콘텐츠. 최소 / 패딩",
  "视口响应 · 容器响应 · 逻辑方向 · 打印展平 · 桌面工作台": "뷰포트 응답성 · 컨테이너 응답성 · 논리적 방향 · 인쇄 병합 · 데스크탑 워크벤치",
  "视口小于 768px 时，多栏、Master / Detail 和检查器布局按语义顺序纵向排列；Dock 默认只保留主区，可用": "뷰포트가 768px보다 작은 경우 다중 열, 마스터/세부 사항 및 검사기 레이아웃이 의미 순서에 따라 수직으로 정렬됩니다. Dock은 기본적으로 기본 영역만 유지하며 사용할 수 있습니다.",
  "视口最小宽度": "뷰포트 최소 너비",
  "视图": "보기",
  "试用": "시험판",
  "是 Gardenerim CSS 2.1.0 的官方 AngularJS 1.x 遗留系统适配层，当前版本为": "는 Gardenerim CSS 2.1.0에 대한 공식 AngularJS 1.x 레거시 시스템 적응 레이어이며, 현재 버전은 다음과 같습니다.",
  "是 Gardenerim CSS 2.1.0 的官方 Razor Class Library，当前版本为": "은 Gardenerim CSS 2.1.0의 공식 Razor 클래스 라이브러리이며, 현재 버전은 다음과 같습니다.",
  "是 Gardenerim CSS 2.1.0 的官方 React 适配层，当前版本为": "는 Gardenerim CSS 2.1.0의 공식 React 적응 레이어이며, 현재 버전은 다음과 같습니다.",
  "是 Gardenerim CSS 2.1.0 的官方 Vue 3 适配层，当前版本为": "는 Gardenerim CSS 2.1.0의 공식 Vue 3 적응 레이어이며, 현재 버전은 다음과 같습니다.",
  "是给生成器使用 Gardenerim 的约束。前者提供界面组件，后者规定选能力、配方、组件和工具类的顺序。": "은 발전기에서 Gardenerim를 사용하기 위한 제약사항입니다. 전자는 인터페이스 구성 요소를 제공하고 후자는 기능, 레시피, 구성 요소 및 도구 클래스가 선택되는 순서를 지정합니다.",
  "是公共命名与程序接口的规范清单，完整登记 CSS 层、包入口、主题属性、JavaScript 导出、行为、事件、桌面适配器和兼容字段。": "은 CSS 레이어, 패키지 항목, 테마 속성, JavaScript 내보내기, 동작, 이벤트, 데스크톱 어댑터 및 호환성 필드를 완전히 등록하는 공개 이름 지정 및 프로그래밍 인터페이스의 표준 목록입니다.",
  "是五个公共区域；": "은 5개의 공통 영역입니다.",
  "是预压缩单文件入口。SSR 导入不访问浏览器全局对象，行为只在组件挂载后初始化，因此可用于服务端渲染与 Hydration。": "은 사전 압축된 단일 파일 항목입니다. SSR 가져오기는 브라우저 전역 개체에 액세스하지 않으며 구성 요소가 마운트된 후에만 동작이 초기화되므로 서버 측 렌더링 및 Hydration에 사용할 수 있습니다.",
  "适合 WebView": "WebView에 적합",
  "适用场景": "적용 가능한 시나리오",
  "释放监听器、计时器和实例引用。": "리스너, 타이머 및 인스턴스 참조를 해제합니다.",
  "收藏": "컬렉션",
  "收录完整 42 个颜色主题，默认保持白底 Light 与小圆角 small。 6 个作用域服务为": "기본 흰색 배경이 밝고 작고 둥근 모서리가 작은 42가지 색상 테마가 포함되어 있습니다. 6가지 범위 서비스는 다음과 같습니다.",
  "收入": "소득",
  "收入上升": "매출이 오른다",
  "手机验证": "휴대폰 인증",
  "手势、按钮与 Escape 均可操作。": "제스처, 버튼, Escape를 모두 사용할 수 있습니다.",
  "手势提示": "제스처 프롬프트",
  "手势只增强效率：Pull Refresh 有刷新按钮路径，Infinite Load 有“加载更多”，Swipe Actions 有 Toggle，Wheel Picker 支持键盘。": "제스처는 효율성만 향상시킵니다. Pull Refresh에는 새로 고침 버튼 경로가 있고, Infinite Load에는 \"추가 로드\"가 있고, Swipe Actions에는 Toggle이 있고, Wheel Picker에는 키보드 지원이 있습니다.",
  "首次密码、资料、组织与安全偏好": "최초 비밀번호, 정보, 조직 및 보안 기본 설정",
  "首次设置": "최초 설정",
  "首次使用也有明确下一步。": "최초 사용을 위한 명확한 다음 단계도 있습니다.",
  "首页": "홈페이지",
  "首页.json": "홈.json",
  "首页封面.jpg": "홈페이지표지.jpg",
  "首页封面上传进度": "홈페이지 표지 업로드 진행",
  "受控产物": "통제 대상 제품",
  "受控值": "제어값",
  "受控值、自定义事件与行为实例": "제어되는 값, 맞춤 이벤트 및 동작 인스턴스",
  "受信任设备": "신뢰할 수 있는 장치",
  "授权同意": "승인 및 동의",
  "舒适、标准和紧凑密度": "편안함, 표준 및 컴팩트 밀도",
  "输出前校验端点、键盘、焦点、状态、RTL、打印和高对比环境。": "출력하기 전에 엔드포인트, 키보드, 포커스, 상태, RTL, 인쇄 및 고대비 환경을 확인하십시오.",
  "输入发送到 +86 138****6608 的验证码": "+86 138****6608로 전송된 인증번호를 입력하세요",
  "输入类名、完整选择器、CSS 属性、值或响应条件。为避免一次渲染 11,498 项，至少输入两个字符后分批显示，每次 100 项；输入": "클래스 이름, 전체 선택기, CSS 속성, 값 또는 응답 조건을 입력합니다. 한 번에 11,498개 항목을 렌더링하지 않으려면 한 번에 100개 항목을 일괄 표시하기 전에 두 문자 이상을 입력하십시오. 들어가다",
  "输入命令": "명령어 입력",
  "输入命令或文件名": "명령 또는 파일 이름을 입력하세요.",
  "属性": "속성",
  "属性 / 触发": "속성/트리거",
  "属性、样式、审计、上下文信息": "속성, 스타일, 감사, 상황별 정보",
  "属性的真实源码命中，将 506 个组件解析到一个或多个完整所属包，而不是截取单个选择器，因此伪类、状态、动画、子部件、容器查询和依赖规则不会丢失。": "속성에 대한 실제 소스 코드 적중은 개별 선택기를 자르는 대신 506개의 구성 요소를 하나 이상의 완전한 소속 패키지로 확인하므로 의사 클래스, 상태, 애니메이션, 하위 부분, 컨테이너 쿼리 및 종속성 규칙이 손실되지 않습니다.",
  "术语、缩写与行业概念解释入口": "용어, 약어 및 산업 개념 설명 포털",
  "树 · 画布 · 检查器": "나무 · 캔버스 · 인스펙터",
  "数据": "데이터",
  "数据不只要显示，还要立即可用": "데이터는 표시되어야 할 뿐만 아니라 즉시 사용할 수 있어야 합니다.",
  "数据操作": "데이터 연산",
  "数据属性": "데이터 속성",
  "数据展示与操作": "데이터 표시 및 조작",
  "数据展示与操作模式清单": "데이터 표시 및 동작 모드 목록",
  "数据展示与操作组合": "데이터 표시 및 동작 조합",
