  "数量": "수량",
  "数量步进": "수량 단계",
  "数量联动、": "수량연계,",
  "数值 + 固定/可选单位": "수치값 + 고정/옵션 단위",
  "数值、标签与小趋势图": "값, 라벨 및 작은 추세 차트",
  "数字": "번호",
  "双侧栏": "더블 사이드바",
  "双重产物预算": "이중 제품 예산",
