  "顺序": "시퀀스",
  "说明": "설명",
  "四边使用": "양면 사용",
  "搜索": "검색",
  "搜索 AngularJS 组件": "AngularJS 구성 요소 검색",
  "搜索 Blazor 组件": "Blazor 구성 요소 검색",
  "搜索 CSS API": "CSS API 검색",
  "搜索 GButton、dialog、标签、选择器、类别、状态或平台": "GButton, 대화상자, 라벨, 선택기, 카테고리, 상태 또는 플랫폼 검색",
  "搜索 GButton、dialog、选择器、类别、状态、行为或平台": "GButton, 대화상자, 선택기, 카테고리, 상태, 동작 또는 플랫폼 검색",
  "搜索 GButton、dialog、选择器、类别、状态或平台": "GButton, 대화상자, 선택기, 카테고리, 상태 또는 플랫폼 검색",
  "搜索 GButtonDirective、gButton、dialog、类别、状态或平台": "GButtonDirective, gButton, 대화 상자, 카테고리, 상태 또는 플랫폼 검색",
  "搜索 React 组件": "React 구성요소 검색",
  "搜索 Vue 组件": "Vue 구성 요소 검색",
  "搜索、筛选、结果数和操作": "검색, 필터링, 결과 개수 및 작업",
  "搜索帮助": "검색 도움말",
  "搜索帮助…": "검색 도움말…",
  "搜索工具类": "검색 도구",
  "搜索名称、类别、选择器、部件、状态或平台": "이름, 카테고리, 선택기, 부품, 상태 또는 플랫폼 검색",
  "搜索内容": "콘텐츠 검색",
  "搜索全部 CSS 接口": "모든 CSS 인터페이스 검색",
  "搜索完整工具类清单": "전체 도구 목록 검색",
  "搜索文件": "파일 검색",
  "搜索页面或内容": "페이지 또는 콘텐츠 검색",
  "搜索组件": "검색 구성요소",
  "缩进层级、父子行展开": "들여쓰기 수준, 상위-하위 줄 확장",
  "缩略图、名称、属性和快捷动作": "썸네일, 이름, 속성 및 빠른 동작",
  "缩略图网格与媒体多选": "썸네일 그리드 및 미디어 다중 선택",
  "所有 32 模式均进入组件 Manifest 和动态组件目录；CSS 源码完整 API 也会列出模块、选择器、变量和状态。": "32개 모드는 모두 구성 요소 매니페스트 및 동적 구성 요소 디렉터리에 들어갑니다. CSS 소스 전체 API에는 모듈, 선택기, 변수 및 상태도 나열됩니다.",
  "所有结构采用逻辑方向属性并支持 RTL；Forced Colors 提供选择轮廓；打印隐藏数据操作，展开详情和层级行，并移除滚动裁切。": "모든 구조는 논리적 방향 속성을 채택하고 RTL을 지원합니다. 강제 색상은 선택 윤곽선을 제공합니다. 숨겨진 데이터 작업을 인쇄하고, 세부 정보 및 계층 구조 행을 확장하고, 스크롤 클리핑을 제거합니다.",
  "所有开始、结束和操作对齐使用逻辑方向；Floating Action Bar、Back to Top 同时读取设备安全区。": "모든 시작, 종료 및 작업 정렬은 논리적 방향을 사용합니다. 플로팅 작업 표시줄, 맨 위로 이동은 장치 안전 영역도 읽습니다.",
  "所有模式覆盖键盘、RTL、Reduced Motion、Forced Colors 与打印；移动结算尊重 Safe Area，打印隐藏购买动作并保留订单、发票和税费信息。": "모든 모드에는 키보드, RTL, 움직임 감소, 강제 색상 및 인쇄가 포함됩니다. 모바일 청구서는 안전 영역을 존중하며 인쇄 시 구매 조치를 숨기고 주문, 송장 및 세금 정보를 유지합니다.",
  "所有模式使用白色 Surface、1px 边框和4px小圆角；在 960/704/512px 容器宽度下折叠 Artifact、Sidebar 与双列模式，并覆盖 RTL、Forced Colors 和打印。": "모든 모드에서 흰색 표면, 1px 테두리 및 4px 작은 둥근 모서리를 사용합니다. 아티팩트, 사이드바 및 이중 열 모드를 960/704/512px 컨테이너 너비로 축소하고 RTL, 강제 색상 및 인쇄를 재정의합니다.",
  "所有模式使用逻辑方向并覆盖 RTL、Reduced Motion、Forced Colors 和打印；打印隐藏上传与编辑动作，展平滚动区并保留正文和修订信息。": "모든 모드는 논리적 방향을 사용하고 RTL, 감소된 동작, 강제 색상 및 인쇄를 포함합니다. 인쇄는 업로드 및 편집 작업을 숨기고 스크롤 영역을 병합하며 텍스트 및 개정 정보를 유지합니다.",
  "所有水平语义使用 inline/start/end；Media Object、Bleed、Imposter、Overlay、Reel 和 Scroll Snap 支持 RTL。": "모든 수평 의미는 인라인/시작/끝을 사용합니다. 미디어 개체, 블리드, 임포스터, 오버레이, 릴 및 스크롤 스냅은 RTL을 지원합니다.",
  "所有图片有符合目的的": "모든 이미지는 목적에 적합합니다.",
  "所有样式覆盖 RTL、Reduced Motion、Forced Colors 与打印。打印隐藏密码、Provider、倒计时和敏感操作，只保留必要的安全审计信息。": "모든 스타일에는 RTL, 모션 감소, 강제 색상 및 인쇄가 포함됩니다. 필요한 보안 감사 정보만 유지하면서 숨겨진 비밀번호, 공급자, 카운트다운 및 민감한 작업을 인쇄합니다.",
  "所有原生 attributes、DOM 事件和 slots 均透传。组件模板 Ref 统一公开": "모든 기본 속성, DOM 이벤트 및 슬롯이 전달됩니다. 컴포넌트 템플릿 참조 통합 공개",
  "所有组合使用逻辑方向属性；Input Group、Money、Unit、字段动作和 Sticky Actions 在 RTL 下保持正确首尾关系。": "모든 조합은 논리적 방향 속성을 사용합니다. 입력 그룹, 돈, 단위, 필드 작업 및 고정 작업은 RTL에서 올바른 일대일 관계를 유지합니다.",
  "锁屏": "잠금화면",
  "套餐、版本和能力横向比较": "패키지, 버전, 기능의 수평적 비교",
  "提供 640px 容器折叠；移动端 Picker Panel 自动成为底部面板，Batch Toolbar 避让安全区。": "640px 컨테이너 축소를 제공합니다. 모바일 선택기 패널은 자동으로 하단 패널이 되고 배치 도구 모음은 안전 영역을 피합니다.",
  "提供 Unicode 搜索、网格/列表切换、单项选择、方向键、Home、End、Enter 和 Space，并发布选择事件。": "유니코드 검색, 그리드/목록 전환, 단일 선택, 화살표 키, Home, End, Enter 및 Space를 제공하고 선택 이벤트를 게시합니다.",
  "提供传统 12 栅格。两者都使用原生 CSS Grid、逻辑方向和统一断点，不依赖负边距。": "기존의 12그리드를 제공합니다. 둘 다 기본 CSS 그리드, 논리적 방향 및 통합 중단점을 사용하며 음수 여백에 의존하지 않습니다.",
  "提供每个页面的端、部件、运行时和用途；": "각 페이지의 터미널, 위젯, 런타임 및 목적을 제공합니다.",
