  "先建立租户与身份边界，再组织内容工作流、Dashboard 和门户页面。": "콘텐츠 워크플로, 대시보드 및 포털 페이지를 구성하기 전에 테넌트 및 ID 경계를 설정하십시오.",
  "先判断导航范围（全局、局部、层级或页内），再判断方向和终端；Tabs 只切换同一上下文内的视图，Breadcrumb 只表达位置，Pagination 只表达结果集翻页，不应互相替代。": "먼저 탐색 범위(글로벌, 로컬, 계층적 또는 페이지 내)를 결정한 다음 방향과 터미널을 결정합니다. 탭은 동일한 컨텍스트 내의 뷰만 전환하고, 이동 경로는 위치만 표현하며, 페이지 매김은 결과 세트 페이지 전환만 표현하며 서로 대체되어서는 안 됩니다.",
  "先判断数据形态，再判断操作强度。少量静态属性用 Description List 或 Key Value；多记录用 List 或 Table；单元格需要键盘移动和编辑时才使用 Data Grid；层级数据使用 Tree 或 Tree Table；趋势和比较先提供可读数值，再增加图形。": "먼저 데이터 형식을 결정한 다음 작업 강도를 결정합니다. 소수의 정적 속성에 대해서는 설명 목록 또는 키 값을 사용하십시오. 여러 레코드에 대해 목록 또는 테이블을 사용합니다. 셀에 키보드 이동 및 편집이 필요한 경우에만 데이터 그리드를 사용하십시오. 계층적 데이터에는 트리 또는 트리 테이블을 사용합니다. 추세와 비교는 먼저 읽을 수 있는 값을 제공한 다음 그래픽을 추가합니다.",
