  "颜色主题只负责品牌主色；显示模式与其他主题轴相互独立。本站固定使用 Light，以保持白色文档体验，但框架同时提供 Dark、System 与 High Contrast。": "컬러 테마는 브랜드의 메인 컬러만을 담당합니다. 표시 모드는 다른 테마 축과 독립적입니다. 이 사이트는 흰색 문서 환경을 유지하기 위해 Light를 사용하지만 프레임워크는 Dark, System 및 High Contrast도 제공합니다.",
