  "页面不能只实现正常数据态。至少要明确 Loading、Empty、Error；面向路由和完整应用时还应准备 403、404、500、Offline 和 Maintenance。Gardenerim 为这些状态提供相同的内容、视觉、详情、操作和帮助部件。": "페이지가 일반 데이터 상태만 구현할 수 없습니다. 최소한 로드 중, 비어 있음 및 오류가 지워져야 합니다. 라우팅 및 완전한 애플리케이션을 위해 403, 404, 500, 오프라인 및 유지 관리도 준비되어야 합니다. Gardenerim는 이러한 상태에 대해 동일한 콘텐츠, 시각 자료, 세부 정보, 작업 및 도움말 위젯을 제공합니다.",
