  "营销、个人和内容页使用自然文档滚动；Dashboard 与工作台允许高密度多栏；医疗、金融和政务只是 UI 契约，不替代法规、身份验证、隐私、审计和后端业务规则。": "마케팅, 개인 및 콘텐츠 페이지는 자연 문서 스크롤을 사용합니다. 대시보드 및 워크벤치는 고밀도 다중 열을 허용합니다. 의료, 재무 및 정부는 UI 계약일 뿐이며 규정, 인증, 개인 정보 보호, 감사 및 백엔드 비즈니스 규칙을 대체하지 않습니다.",
