  "用于真实验证 24 / 12、RTL、Container Query 与打印结构。构建检查会逐项验证所有类，而不是只检查几个示例。": "24/12 실시간 검증을 위해 RTL, Container Query 및 프린팅 구조를 제공합니다. 빌드 확인은 단지 몇 가지 예를 확인하는 대신 모든 클래스를 하나씩 확인합니다.",
  "用于直接读取上下文。默认仍是白色 Light 与小圆角，不会自动启用深色主题。": "컨텍스트를 직접 읽기 위한 것입니다. 기본값은 여전히 ​​작은 둥근 모서리가 있는 흰색 조명이며, 어두운 테마는 자동으로 활성화되지 않습니다.",
