  "与 Node.js": "Node.js 사용",
  "与安全 preload，只暴露 Minimize、Maximize/Restore、Close 等白名单方法；不要开启 Node Integration，也不要把任意 IPC 通道暴露给页面。": "보안 사전 로드를 사용하면 최소화, 최대화/복원 및 닫기와 같은 화이트리스트 방법만 노출됩니다. 노드 통합을 활성화하지 말고 IPC 채널을 페이지에 노출하지 마십시오.",
  "与当前页面或表单上下文绑定的帮助": "현재 페이지 또는 양식 컨텍스트에 바인딩된 도움말",
