  "元素或属性形式提供十轴主题并初始化子树": "요소 또는 속성 폼은 10축 테마를 제공하고 하위 트리를 초기화합니다.",
  "元素指令、属性指令与语义": "요소 지시어, 속성 지시어 및 의미론",
