  "原生 attributes、事件、children 与": "기본 속성, 이벤트, 하위 및",
  "原生 input 后备；发出": "기본 입력 대체; 방출",
  "原生 input、textarea 和 select 的模型语义仍由 AngularJS 自己管理，适配层不会覆盖": "기본 입력, 텍스트 영역 및 선택의 모델 의미는 여전히 AngularJS 자체에서 관리되며 적응 레이어에서 다루지 않습니다.",
  "原生 input/change 自动去重": "기본 입력/변경의 자동 중복 제거",
  "原生标题栏、窗口按钮、菜单和活动栏只是起点；文档标签、可调分栏、Dock、检查器、命令面板、文件选择、托盘、多窗口、后台任务、更新、权限与崩溃恢复均已有稳定组合，可直接落地 Tauri 与 Electron。": "기본 제목 표시줄, 창 버튼, 메뉴 및 활동 표시줄은 시작점일 뿐입니다. 문서 레이블, 조정 가능한 열, Dock, 검사기, 명령 패널, 파일 선택, 트레이, 다중 창, 백그라운드 작업, 업데이트, 권한 및 충돌 복구가 모두 안정적으로 결합되었으며 Tauri 및 Electron에서 직접 구현할 수 있습니다.",
  "原生表单和自定义 Gardenerim 事件均支持": "기본 형식과 사용자 정의 Gardenerim 이벤트가 모두 지원됩니다.",
  "原生权限请求、网络状态、数据加载、支付、认证和媒体缩放由业务或宿主实现；Gardenerim 提供稳定视觉、状态、事件与无障碍接口，不伪造结果。": "기본 권한 요청, 네트워크 상태, 데이터 로딩, 결제, 인증 및 미디어 확장은 비즈니스 또는 호스트에 의해 구현됩니다. Gardenerim는 결과를 위조하지 않고도 안정적인 비전, 상태, 이벤트 및 접근 가능한 인터페이스를 제공합니다.",
  "原始 JSON 清单": "원시 JSON 매니페스트",
  "原始选择器": "오리지널 셀렉터",
  "原语": "원시",
