  "源码/预览双栏和移动折叠": "소스코드/미리보기 이중열 및 모바일 폴딩",
  "源码模块": "소스코드 모듈",
  "远山设计": "위안산 디자인",
  "约定": "계약",
  "约束。": "제약.",
  "阅读 AngularJS 文档": "AngularJS 문서 읽기",
  "阅读 Blazor 文档": "Blazor 문서 읽기",
  "阅读 React 文档": "React 문서 읽기",
  "阅读 Vue 文档": "Vue 문서 읽기",
  "阅读宽度、水平或内容居中；max / gutter": "읽기 너비, 수준 또는 콘텐츠 센터; 최대/거터",
  "阅读文档": "문서 읽기",
  "允许后续 1.x 新增，禁止无迁移路径的删除；在 2.1.0 稳定切点还会反向检查已有入口是否漏记。废弃入口至少保留两个次版本，并只能在新的主版本移除。其闭合结构由": "마이그레이션 경로 없이 후속 1.x 추가를 허용하고 삭제를 금지합니다. 2.1.0 안정 컷오프 지점에서는 기존 항목도 역으로 검사되어 누락되었는지 확인합니다. 더 이상 사용되지 않는 항목은 두 개 이상의 부 버전에 남아 있으며 새 주요 버전에서만 제거할 수 있습니다. 닫힌 구조는 다음과 같이 구성됩니다.",
  "允许写入页面模板？": "페이지 템플릿에 쓰기를 허용하시겠습니까?",
  "允许一次": "1회 허용",
  "运行环境": "동작환경",
  "运行时": "런타임",
  "运行时，根据滚动位置显示，点击后平滑返回顶部；Reduced Motion 环境自动使用即时滚动。": "런타임 시 디스플레이는 스크롤 위치를 기반으로 하며 클릭 후 원활하게 맨 위로 돌아갑니다. 모션 감소 환경에서는 자동으로 인스턴트 스크롤링을 사용합니다.",
  "运行时、可访问性与环境规则": "런타임, 접근성 및 환경 규칙",
  "运行时测试门禁（0.4.0 起）": "런타임 시 액세스 제어 테스트(0.4.0부터)",
