  "运行时行为新增或改名时，公共 API、示例/补充夹具和逐行为测试必须同步，否则测试会因缺少夹具、实例或成员而失败。": "런타임 동작이 추가되거나 이름이 바뀌면 공개 API, 샘플/보조 고정 장치 및 동작별 테스트를 동기화해야 합니다. 그렇지 않으면 고정 장치, 인스턴스 또는 멤버 누락으로 인해 테스트가 실패합니다.",
