  "正式 CSS 与 JavaScript 使用 esbuild 做语法级压缩，不使用正则替换；主压缩入口和每次自定义构建生成可追溯的外部 Source Map。压缩 CSS 使用不随版本变化的稳定 MIT banner，避免纯版本文本扰动 Brotli 基线，未压缩 CSS 与 Runtime 仍提供精确版本。": "정식 CSS 및 JavaScript는 일반 교체를 사용하지 않고 구문 수준 압축을 위해 esbuild를 사용합니다. 기본 압축 항목과 각 사용자 지정 빌드는 추적 가능한 외부 소스 맵을 생성합니다. 압축된 CSS는 순수한 버전 텍스트가 Brotli 기준을 방해하지 않도록 버전에 따라 변경되지 않는 안정적인 MIT 배너를 사용합니다. 압축되지 않은 CSS와 런타임은 여전히 ​​정확한 버전을 제공합니다.",
