  "字段、分区、水平与行内布局、搜索/密码/计数、选择组、验证、姓名/地址/金额、条件与可重复项、审核和提交动作都已组合好。AI 只需选择业务意图，不必反复组织表单 CSS。": "필드, 파티션, 수평 및 인라인 레이아웃, 검색/비밀번호/계산, 그룹 선택, 유효성 검사, 이름/주소/금액, 조건 및 반복 가능 항목, 검토 및 제출 작업이 모두 결합됩니다. AI는 비즈니스 의도만 선택하면 되며 양식 CSS를 반복해서 구성할 필요가 없습니다.",
  "字段结构、业务选择与进度状态保持一致。": "분야 구조, 사업 선정, 진행 상황이 일관되게 유지됩니다.",
  "字段下方持久说明；成功、警告、危险语义": "필드 아래에 지속적인 설명이 있습니다. 성공, 경고, 위험 의미론",
  "字符": "캐릭터",
  "字符串或只读字符串数组": "문자열 또는 읽기 전용 문자열 배열",
