  "自动布局": "자동 레이아웃",
  "自动初始化。MutationObserver 同时处理新增节点和后加行为属性，适合 SPA、CMS 画布和 AI 流式生成 DOM。": "자동 초기화. MutationObserver는 새로운 노드와 추가된 동작 속성을 동시에 처리하며 SPA, CMS 캔버스 및 AI 스트리밍에 적합하여 DOM을 생성합니다.",
  "自动初始化与动态 DOM 观察": "자동 초기화 및 동적 DOM 관찰",
  "自动高度、Enter/Shift+Enter、": "자동 높이, Enter/Shift+Enter,",
  "自动化": "자동화",
  "自动生成，覆盖每个源码模块、语义类、原始选择器、Token、自定义状态钩子、数据属性和关键帧；工具类使用下一节的专用完整清单。它是源码级目录，不是精选示例。": "모든 소스 코드 모듈, 의미 클래스, 기본 선택기, 토큰, 사용자 정의 상태 후크, 데이터 속성 및 키프레임을 포함하여 자동으로 생성됩니다. 도구 클래스의 경우 다음 섹션의 전용 전체 목록을 사용하세요. 이는 주요 예제가 아닌 소스 수준 디렉터리입니다.",
  "自动推进、退格、方向键、整串粘贴、完成事件": "자동진행, 백스페이스, 방향키, 전체 문자열 붙여넣기, 완료 이벤트",
  "自动完成预检与版本快照。": "실행 전 및 버전 스냅샷을 자동으로 완료합니다.",
  "自动显示、滚动和恢复焦点": "초점 자동 표시, 스크롤 및 복원",
