  "阻止后续操作的流程守卫。": "후속 작업을 방지하는 프로세스 가드입니다.",
  "组成完整结构。不要用单个相似组件冒充整页配方。": "은 완전한 구조를 형성합니다. 하나의 유사한 구성 요소로 전체 페이지 레시피를 전달하지 마십시오.",
