  "组件引用提供 6 个实例成员：": "구성요소 참조는 6개의 인스턴스 멤버를 제공합니다.",
  "组件优先使用 inline/block 方向，减少 RTL 专用覆盖。": "구성요소는 RTL 관련 적용 범위를 줄이기 위해 인라인/블록 방향을 우선적으로 사용합니다.",
  "组件与环境清单": "구성요소 및 환경 목록",
  "组件域入口，全部正式压缩文件均携带外部 Source Map。": "구성 요소 도메인 항목, 모든 공식 압축 파일에는 외부 소스 맵이 포함됩니다.",
  "组件元数据": "구성요소 메타데이터",
  "组件源清单": "컴포넌트 소스 목록",
  "组件只消费语义 Token。品牌定制应覆盖 Token，而不是复制组件规则。": "구성요소는 의미론적 토큰만 소비합니다. 브랜드 사용자 정의는 구성 요소 규칙을 복사하는 대신 토큰을 재정의해야 합니다.",
  "组件状态要求": "구성요소 상태 요구사항",
