  "最小宽度": "최소폭",
  "最新": "최신",
  "作为父级。列宽类保持相同，AI 只需先确定父级系统。": "을 부모로 사용합니다. 열 너비 클래스는 동일하게 유지되며 AI는 상위 시스템만 먼저 결정하면 됩니다.",
  "作为兼容别名保留。按组件名构建时，构建器依据类选择器与": "호환 가능한 별칭으로 예약되어 있습니다. 구성 요소 이름으로 빌드하는 경우 빌더는 클래스 선택기에 따라 달라지며",
  "作者可使用的 331 个属性被划分为上方行为契约中的 72 个行为入口、178 个结构/动作选择器和 81 个附加配置属性；另有 29 个由运行时维护的状态属性。状态属性可能同时作为初始配置读取，但作者可用的前三组彼此互斥，不会重复计数。": "작성자가 사용할 수 있는 331개 속성은 위 동작 계약의 동작 항목 72개, 구조/동작 선택기 178개, 추가 구성 속성 81개로 나뉩니다. 런타임에 의해 유지되는 29개의 상태 속성도 있습니다. 상태 속성은 초기 구성과 동시에 읽을 수 있지만 작성자가 사용할 수 있는 처음 세 세트는 상호 배타적이며 이중으로 계산되지 않습니다.",
