  "Axe 门禁阻断所选 WCAG A/AA 规则检测到的全部违规，不按 impact 降级放行，并输出规则、节点选择器、HTML 与修复摘要。自动化不能代替人工屏幕阅读器测试；正式产品仍应使用 NVDA / JAWS / VoiceOver 完成关键任务走查。": "Axe Gate blocks all violations detected by the selected WCAG A/AA rules, passes them without downgrade by impact, and outputs the rule, node selector, HTML, and remediation summary. Automation cannot replace human screen reader testing; production products should still use NVDA/JAWS/VoiceOver for mission-critical walkthroughs.",
  "Axe WCAG 2 A/AA 全部自动违规归零，并覆盖键盘与焦点恢复、RTL、Reduced Motion、Forced Colors。": "Axe WCAG 2 A/AA 모든 자동적인 위반은 키보드와 초점 회복, RTL, 감소된 운동, 강제적인 색깔을 포함합니다.",
