  "Bottom Sheet 适合短任务，Action Sheet 适合动作列表，Filter Sheet 适合筛选；复杂编辑使用 Fullscreen Dialog，破坏性确认仍使用专用 Dialog。": "하단 시트는 짧은 작업에 적합하고, 액션 시트는 작업 목록에 적합하며, 필터 시트는 필터링에 적합합니다. 복잡한 편집에는 전체 화면 대화 상자를 사용하고, 파괴적인 확인에는 여전히 전용 대화 상자를 사용합니다.",
