  "Gardenerim": "Gardenerim",
  "Gardenerim — 为所有界面准备好的 CSS 基础设施": "Gardenerim — 모든 인터페이스에 준비된 CSS 인프라",
  "Gardenerim 把基础 CSS、交互组件、业务配方、桌面端适配与机器可读清单放进同一套系统。人可以直接开发，AI 可以准确选用，无需每次重新组织样式。": "Gardenerim는 기본 CSS, 대화형 구성요소, 비즈니스 레시피, 데스크탑 적응 및 기계 판독 가능 매니페스트를 하나의 시스템에 통합합니다. 사람이 직접 개발할 수 있고, AI가 매번 스타일을 재구성할 필요 없이 정확하게 선택해서 사용할 수 있다.",
  "Gardenerim 可以只使用 CSS，也可以加载零依赖运行时获得交互行为。完整包默认包含所有主题、组件和工具类。": "Gardenerim는 CSS만 사용하거나 상호 작용하는 행동을 위한 영 의존성 런타임을 적재할 수 있습니다. 전체 패키지에는 모든 테마, 구성 요소 및 도구 클래스가 기본적으로 포함되어 있습니다.",
  "Gardenerim 是面向人类开发者与 AI 页面生成器的通用 CSS、Vue 3、React、AngularJS 与 Blazor 组件、页面配方及桌面应用基础设施。": "Gardenerim는 인간 개발자와 AI 페이지 빌더를 위한 범용 CSS, Vue 3, React, AngularJS 및 Blazor 구성 요소, 페이지 레시피 및 데스크톱 애플리케이션 인프라입니다.",
  "Gardenerim 首页": "Gardenerim 홈 페이지",
  "Gardenerim 完整文档：CSS、Vue 3、React、AngularJS、Blazor、主题、Token、工具类、506 个组件、运行时、完整页面、AI 页面生成及桌面端适配。": "Gardenerim 전체 문서: CSS, Vue 3, React, AngularJS, Blazor, 테마, 토큰, 도구 클래스, 506 구성 요소, 실행 시간, 완전한 페이지, AI 페이지 생성 및 데스크탑 적응.",
  "Gardenerim 为 AI 提供五层事实来源：公共 API 清单回答“允许使用什么稳定名称与入口”，能力清单回答“行业常规能力是否实现”，组件清单回答“有什么”，工具类清单回答“精确类名是什么”，配方清单回答“复杂页面怎样开始”。": "Gardenerim는 AI에 대한 5개 레이어의 진실 소스를 제공합니다. 공개 API 목록은 \"무엇이 안정적인 이름과 항목을 사용할 수 있는지\"에 답하고, 기능 목록은 \"업계의 일반 기능이 구현되는지 여부\"에 답하고, 구성 요소 목록은 \"무엇이 있습니까?\"에 답하고, 도구 클래스 목록은 \"정확한 클래스 이름은 무엇입니까\"에 답하고, 레시피 목록은 \"복잡한 페이지를 시작하는 방법\"에 답합니다.",
