  "Public API、组件、工具类、配方与行业能力五类清单，把允许使用的名称、入口、平台、状态和响应条件结构化暴露出来，页面生成过程可以被约束、验证和复现。": "공용 API, 구성 요소, 도구 클래스, 레시피 및 산업 기능의 5개 범주 목록은 허용된 이름, 입구, 플랫폼, 상태 및 응답 조건을 구조화된 방식으로 노출합니다. 페이지 생성 프로세스를 제한하고 검증하고 재현할 수 있습니다.",
