  "Recipe 确定整页类型，再选择平台、主题轴和密度。": "레시피 전체 페이지 유형을 결정한 다음 플랫폼, 주제 축 및 밀도를 선택합니다.",
  "recipe.id": "레시피.id",
  "Recipes": "레시피",
  "Record Detail": "기록상세",
  "Recovery Codes": "복구 코드",
  "Reduced Motion": "움직임 감소",
  "Reduced Motion 关闭 Drawer、Tree 与 Skip Link 过渡；Forced Colors 提供显式当前项轮廓；打印隐藏操作导航，保留 Breadcrumb、文档前后页与流程信息。": "동작 감소는 서랍, 트리 및 링크 건너뛰기 전환을 끕니다. 강제 색상은 명시적인 현재 항목 개요를 제공합니다. 인쇄하면 작업 탐색이 숨겨지고 이동 경로, 문서 앞/뒤 페이지, 프로세스 정보가 유지됩니다.",
  "Reduced Motion 降低保存动画；打印隐藏密码、清空、增删和提交动作，保留字段值、验证与审核信息。": "모션 감소는 저장 애니메이션을 줄입니다. 숨겨진 비밀번호, 지우기, 추가, 삭제 및 제출 작업을 인쇄하고 필드 값, 확인 및 감사 정보를 유지합니다.",
  "Reel": "릴",
  "Refund Status": "환불 상태",
  "Registration": "등록",
  "Relation Picker": "관계 선택기",
  "Release 构建为 0 警告、0 错误；506 个组件全部经过真实静态 SSR。浏览器矩阵覆盖 Chromium、Firefox、WebKit、桌面与移动视口、键盘和 Axe WCAG A/AA；CI 强制 Firefox。 NuGet 使用隔离缓存真实发布消费应用，并验证静态 Web Assets endpoint manifest；另有独立 .NET 11 Preview 包消费者。程序集实测 350,208 B，45 个静态资源共 7,820,065 B，CSS gzip 140,386 B，runtime gzip 33,149 B，Blazor bridge gzip 2,097 B，nupkg 约 1.27 MiB、低于 6,000,000 B 硬上限；全部低于硬预算且 DLL/XML 可复现。": "경고 0개, 오류 0개로 릴리스 빌드; 506개의 구성 요소가 모두 진정한 정적 SSR을 통과했습니다. 브라우저 매트릭스에는 Chromium, Firefox, WebKit, 데스크톱 및 모바일 뷰포트, 키보드, Ax WCAG A/AA가 포함됩니다. CI는 Firefox를 의무화합니다. NuGet은 격리된 캐시를 사용하여 실제로 소비자 애플리케이션을 게시하고 정적 웹 자산 엔드포인트 매니페스트의 유효성을 검사합니다. 독립 실행형 .NET 11 Preview 패키지 소비자도 있습니다. 측정된 어셈블리는 350,208 B, 45개 정적 리소스 총 7,820,065 B, CSS gzip 140,386 B, 런타임 gzip 33,149 B, Blazor 브리지 gzip 2,097 B, nupkg 약 1.27 MiB, 6,000,000 B 하드 제한 미만입니다. 모두 하드 예산과 DLL/XML 재생산이 가능합니다.",
  "Release confidence · 2.1.0": "릴리스 신뢰도 · 2.1.0",
  "Release-ready delivery · 2.1.0": "출시 준비 완료 · 2.1.0",
