  "Roving Nav 支持横向/纵向、RTL、四方向键、Home 与 End；Context Menu 支持鼠标右键、键盘菜单键、Shift+F10、Escape 和焦点恢复。": "Roving Nav는 가로/세로, RTL, 4방향 키, 홈 및 끝을 지원합니다. 상황에 맞는 메뉴는 마우스 오른쪽 버튼, 키보드 메뉴 키, Shift+F10, Esc 및 포커스 복구를 지원합니다.",
