  "Tauri 与 Electron 共用标题栏、窗口控制、活动栏、编辑区、检查器、分栏与状态栏，桥接接口保持安全。": "Tauri와 Electron은 제목 표시줄, 창 컨트롤, 활동 표시줄, 편집 영역, 검사기, 열 및 상태 표시줄을 공유하며 브리지 인터페이스는 안전하게 유지됩니다.",
  "Tauri 与 Electron 入口相互隔离，均返回带": "타우리 입구와 전자 입구가 서로 분리되어 있으며 둘 다 벨트로 돌아갑니다.",
  "Tauri v2": "Tauri의 v2",
  "Tauri v2 由应用注入 Window API；权限能力、文件系统、Updater、Deep Link、Tray 与多窗口按应用 Capability 配置，不由 CSS 自动申请。": "Tauri v2는 애플리케이션에 의해 Window API에 주입됩니다. 권한 기능, 파일 시스템, 업데이터, 딥링크, 트레이, 멀티 윈도우는 애플리케이션 기능에 따라 구성되며 CSS에 의해 자동으로 적용되지 않습니다.",
  "Tauri/Electron 工作台主功能切换": "Tauri/Electron 작업대 주요 기능 엇바꾸기",
  "Tauri/Electron 中可把 CRM、Project、Dashboard、Settings 和 Notification 根页放入": "CRM, 프로젝트, 대시보드, 설정 및 알림 루트 페이지를 Tauri/Electron에 배치할 수 있습니다.",
  "Tax Summary": "세금 요약",
