  "Thinking 默认展示可读的推理摘要或进度，不要求泄露模型私有推理链；产品需明确区分“摘要”“工具日志”和“最终答案”。": "Thinking은 기본적으로 읽을 수 있는 추론 요약 또는 진행 상황을 표시하며 모델 비공개 추론 체인을 공개할 필요가 없습니다. 제품은 \"요약\", \"도구 로그\" 및 \"최종 답변\"을 명확하게 구분해야 합니다.",
