  "Tooltip、Popover、Callout、FAQ、帮助中心、Tour、Spotlight、新功能提示、排错和反馈全部使用稳定接口。用户在任何端遇到疑问，都有合适而一致的表达方式。": "도구 설명, 팝오버, 콜아웃, FAQ, 도움말 센터, 둘러보기, 스포트라이트, 새로운 기능 팁, 문제 해결 및 피드백은 모두 안정적인 인터페이스를 사용합니다. 사용자는 어느 쪽에서든 질문을 만나면 적절하고 일관된 표현을 사용합니다.",
